from taf.rfrl.procedures.resources.python.status_check.status_selector.StatusSelector import StatusSelector


class Ald(object):

    _status_selector = StatusSelector()

    @classmethod
    def get_expected_statuses(cls, variant):
        """
        Returns expected values of statuses for given variant.
        :param variant: variant of expected statuses, can be: 'active', 'online', 'offline', 'not_installed',
                                                              'sw_resetting' or 'calibrating'.
        :type variant: str
        :return: dictionary with statuses names as keys and expected statuses values as values
        :rtype: dict(str, str)
        """
        if variant == 'active':
            return cls._get_active_statuses()
        elif variant == 'online':
            return cls._get_online_statuses()
        elif variant == 'offline':
            return cls._get_offline_statuses()
        elif variant == 'not_installed':
            return cls._get_not_installed_statuses()
        elif variant in ['sw_resetting', 'calibrating']:
            return cls._get_sw_resetting_calibrating_statuses()

    @classmethod
    def _get_active_statuses(cls):
        return {"operationalState": cls._status_selector.select_operational_state(variant='enabled'),
                "administrativeState": cls._status_selector.select_administrative_state(variant='unlocked'),
                "availabilityStatus": cls._status_selector.select_availability_status(variant='online'),
                "usageState": "Active",
                "proceduralStatus": None}

    @classmethod
    def _get_online_statuses(cls):
        return {"operationalState": cls._status_selector.select_operational_state(variant='enabled'),
                "administrativeState": cls._status_selector.select_administrative_state(variant='unlocked'),
                "availabilityStatus": cls._status_selector.select_availability_status(variant='online'),
                "proceduralStatus": None}

    @classmethod
    def _get_offline_statuses(cls):
        return {"operationalState": cls._status_selector.select_operational_state(variant='disabled'),
                "administrativeState": cls._status_selector.select_administrative_state(variant='unlocked'),
                "usageState": "Idle",
                "proceduralStatus": "not_initialized",
                "availabilityStatus": cls._status_selector.select_availability_status(variant='offline')}

    @classmethod
    def _get_not_installed_statuses(cls):
        return {"operationalState": cls._status_selector.select_operational_state(variant='disabled'),
                "administrativeState": cls._status_selector.select_administrative_state(variant='unlocked'),
                "usageState": "Idle",
                "proceduralStatus": "not_initialized",
                "availabilityStatus": cls._status_selector.select_availability_status(variant='not_installed')}

    @classmethod
    def _get_sw_resetting_calibrating_statuses(cls):
        return {"operationalState": cls._status_selector.select_operational_state(variant='enabled'),
                "administrativeState": cls._status_selector.select_administrative_state(variant='unlocked'),
                "usageState": "Busy",
                "proceduralStatus": "initializing",
                "availabilityStatus": cls._status_selector.select_availability_status(variant='online')}
